package com.enterpriseflow.repository; import com.enterpriseflow.entity.Meeting; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.EntityGraph; import java.util.*; public interface MeetingRepository extends JpaRepository<Meeting,UUID>{List<Meeting> findAllByOrderByScheduledAtDesc(); @EntityGraph(attributePaths={"organizer","invitees"}) List<Meeting> findByProjectIdOrderByScheduledAtDesc(UUID projectId);}
